package com.mddiet.pro;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.text.InputType;import android.view.*;import android.widget.*;import java.text.SimpleDateFormat;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root,mealsBox;SharedPreferences sp;EditText name,age,height,weight,target,tBreakfast,tSnack,tLunch,tDinner;Spinner sex,activity,goal;TextView result,caloriesLeft,completedCount,planTitle,latestWeight;Switch waterSwitch;WeightChartView chart;int calories=1850,today;int green=Color.rgb(31,122,90),bg=Color.rgb(244,247,245),border=Color.rgb(220,228,224);
 int dp(int v){return(int)(v*getResources().getDisplayMetrics().density);}GradientDrawable rounded(int color,int radius,int stroke){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));if(stroke!=0)g.setStroke(dp(1),stroke);return g;}TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(28,35,32));if(bold)t.setTypeface(Typeface.DEFAULT_BOLD);t.setGravity(Gravity.RIGHT);t.setTextDirection(View.TEXT_DIRECTION_RTL);t.setPadding(0,dp(4),0,dp(4));return t;}Button button(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setTextSize(14);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:Color.rgb(28,35,32));b.setBackground(rounded(primary?green:Color.rgb(235,242,239),12,0));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(4),dp(4),dp(4),dp(4));b.setLayoutParams(lp);return b;}LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(14),dp(16),dp(14));c.setBackground(rounded(Color.WHITE,18,border));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(14));c.setLayoutParams(lp);return c;}EditText input(String v,boolean num){EditText e=new EditText(this);e.setText(v);e.setTextSize(16);e.setSingleLine(true);e.setGravity(Gravity.RIGHT);e.setTextDirection(View.TEXT_DIRECTION_RTL);e.setPadding(dp(12),dp(10),dp(12),dp(10));e.setBackground(rounded(Color.WHITE,10,border));if(num)e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);return e;}Spinner spinner(String[]items){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,items));return s;}View field(String l,View v){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);TextView x=text(l,13,false);x.setTextColor(Color.GRAY);b.addView(x);b.addView(v);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));b.setLayoutParams(lp);return b;}LinearLayout hrow(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);r.setWeightSum(2);return r;}
 public void onCreate(Bundle b){super.onCreate(b);sp=getSharedPreferences("md_diet",MODE_PRIVATE);NotificationScheduler.createChannels(this);today=MealData.dayIndex(Calendar.getInstance());ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(14),dp(18),dp(14),dp(30));root.setBackgroundColor(bg);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);s.addView(root);buildHeader();buildDashboard();buildMeals();buildProfile();buildTimes();buildWeight();buildSafety();setContentView(s);load();calculate(false);renderMeals();renderWeight();requestNotif();NotificationScheduler.scheduleAll(this);}
 void buildHeader(){TextView t=text("MD Diet Pro V2",26,true);t.setTextColor(green);root.addView(t);root.addView(text("برنامجك اليومي للتخفيف والمتابعة",14,false));}
 void buildDashboard(){LinearLayout c=card();c.addView(text("اليوم",19,true));LinearLayout r=hrow();LinearLayout a=new LinearLayout(this);a.setOrientation(LinearLayout.VERTICAL);a.addView(text("السعرات المتبقية",12,false));caloriesLeft=text("—",24,true);caloriesLeft.setTextColor(green);a.addView(caloriesLeft);LinearLayout d=new LinearLayout(this);d.setOrientation(LinearLayout.VERTICAL);d.addView(text("الوجبات المكتملة",12,false));completedCount=text("—",24,true);d.addView(completedCount);r.addView(a,new LinearLayout.LayoutParams(0,-2,1));r.addView(d,new LinearLayout.LayoutParams(0,-2,1));c.addView(r);latestWeight=text("آخر وزن: —",14,false);c.addView(latestWeight);root.addView(c);}
 void buildMeals(){LinearLayout c=card();planTitle=text("برنامج اليوم",20,true);c.addView(planTitle);mealsBox=new LinearLayout(this);mealsBox.setOrientation(LinearLayout.VERTICAL);c.addView(mealsBox);root.addView(c);}
 void buildProfile(){LinearLayout c=card();c.addView(text("بياناتك وحساب الخطة",19,true));name=input("محمد",false);c.addView(field("الاسم",name));age=input("47",true);c.addView(field("العمر (18+)",age));sex=spinner(new String[]{"رجل","امرأة"});c.addView(field("الجنس",sex));height=input("180",true);c.addView(field("الطول (سم)",height));weight=input("105",true);c.addView(field("الوزن الحالي (كغ)",weight));target=input("90",true);c.addView(field("الوزن الهدف (كغ)",target));activity=spinner(new String[]{"قليل جداً / عمل مكتبي","خفيف","متوسط","عالٍ"});c.addView(field("النشاط",activity));goal=spinner(new String[]{"تنزيل وزن","تثبيت وزن","زيادة وزن"});c.addView(field("الهدف",goal));Button bt=button("احسب واحفظ",true);LinearLayout rr=hrow();rr.addView(bt);c.addView(rr);result=text("",14,false);result.setPadding(0,dp(12),0,0);c.addView(result);bt.setOnClickListener(v->{calculate(true);renderMeals();});root.addView(c);}
 void buildTimes(){LinearLayout c=card();c.addView(text("أوقات التنبيهات",19,true));tBreakfast=input("08:00",false);c.addView(field("الفطور",tBreakfast));tSnack=input("13:00",false);c.addView(field("السناك",tSnack));tLunch=input("17:30",false);c.addView(field("الغداء",tLunch));tDinner=input("20:30",false);c.addView(field("العشاء",tDinner));waterSwitch=new Switch(this);waterSwitch.setText("تذكير ماء كل ساعتين تقريباً");waterSwitch.setTextDirection(View.TEXT_DIRECTION_RTL);c.addView(waterSwitch);Button save=button("حفظ وتفعيل الإشعارات",true);LinearLayout rr=hrow();rr.addView(save);c.addView(rr);save.setOnClickListener(v->{saveTimes();sp.edit().putBoolean("water_enabled",waterSwitch.isChecked()).apply();NotificationScheduler.scheduleAll(this);Toast.makeText(this,"تم حفظ الأوقات والتذكيرات",Toast.LENGTH_SHORT).show();});root.addView(c);}
 void buildWeight(){LinearLayout c=card();c.addView(text("متابعة الوزن",19,true));EditText w=input("",true);w.setHint("مثلاً 104.5");c.addView(field("أدخل وزن اليوم (كغ)",w));Button add=button("سجّل الوزن",true);LinearLayout rr=hrow();rr.addView(add);c.addView(rr);chart=new WeightChartView(this);c.addView(chart,new LinearLayout.LayoutParams(-1,dp(190)));add.setOnClickListener(v->{try{float val=Float.parseFloat(w.getText().toString().trim());if(val<35||val>300)throw new Exception();addWeight(val);w.setText("");renderWeight();}catch(Exception e){Toast.makeText(this,"أدخل وزن صحيح",Toast.LENGTH_SHORT).show();}});root.addView(c);}
 void buildSafety(){LinearLayout c=card();c.addView(text("ملاحظة صحية",18,true));TextView t=text("التطبيق مخصص للبالغين 18+ ويعطي تقديرات عامة فقط. إذا عندك سكري، مرض كلوي أو كبدي، مشاكل قلبية، أدوية تؤثر على الوزن، اضطراب أكل، حمل أو رضاعة، الأفضل مراجعة طبيب أو اختصاصي تغذية.",13,false);t.setTextColor(Color.rgb(105,78,25));c.addView(t);root.addView(c);}
 void calculate(boolean saveNow){try{int a=(int)Double.parseDouble(age.getText().toString().trim());double h=Double.parseDouble(height.getText().toString().trim()),w=Double.parseDouble(weight.getText().toString().trim()),tg=Double.parseDouble(target.getText().toString().trim());if(a<18||a>100||h<130||h>220||w<35||w>300){result.setText("تأكد من البيانات. التطبيق للبالغين 18+ فقط.");return;}boolean male=sex.getSelectedItemPosition()==0;double bmr=10*w+6.25*h-5*a+(male?5:-161);double[]acts={1.2,1.375,1.55,1.725};double tdee=bmr*acts[activity.getSelectedItemPosition()];int g=goal.getSelectedItemPosition();double cal=tdee;if(g==0)cal=tdee*.82;if(g==2)cal=tdee*1.10;int min=male?1500:1200;calories=(int)Math.round(Math.max(min,cal));double bmi=w/Math.pow(h/100.0,2),ref=Math.min(w,Math.max(tg,h*.42));int protein=(int)Math.round(Math.max(1.2*ref,Math.min(1.7*ref,180))),fat=(int)Math.round((calories*.28)/9.0),carbs=Math.max(0,(int)Math.round((calories-protein*4-fat*9)/4.0));double water=Math.min(4.0,Math.max(1.8,w*.03));result.setText("هدف السعرات: "+calories+" سعرة\nاحتياج المحافظة: "+Math.round(tdee)+" سعرة\nBMI تقريبي: "+String.format(Locale.US,"%.1f",bmi)+"\nبروتين: "+protein+"غ   كربوهيدرات: "+carbs+"غ   دهون: "+fat+"غ\nماء تقريبي: "+String.format(Locale.US,"%.1f",water)+" لتر");sp.edit().putInt("calories",calories).apply();if(saveNow){saveProfile();Toast.makeText(this,"تم حفظ الخطة",Toast.LENGTH_SHORT).show();}updateDashboard();}catch(Exception e){result.setText("تأكد من إدخال كل الأرقام بشكل صحيح.");}}
 void renderMeals(){today=MealData.dayIndex(Calendar.getInstance());planTitle.setText("برنامج اليوم — "+MealData.dayName(today));mealsBox.removeAllViews();for(int meal=0;meal<4;meal++){final int m=meal;int swap=sp.getInt("swap_"+today+"_"+m,-1);boolean done=sp.getBoolean(doneKey(today,m),false);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(12),dp(12),dp(12),dp(12));box.setBackground(rounded(Color.rgb(249,251,250),14,border));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(6));box.setLayoutParams(lp);TextView tt=text(MealData.mealName(m)+"   "+MealData.mealCalories(calories,m)+" سعرة تقريباً",17,true);tt.setTextColor(green);box.addView(tt);box.addView(text(MealData.portionText(today,m,calories,swap),15,false));LinearLayout actions=hrow();Button eaten=button(done?"✓ أكلت":"أكلت الوجبة",done),swapBtn=button("بدّل الوجبة",false);actions.addView(eaten);actions.addView(swapBtn);box.addView(actions);eaten.setOnClickListener(v->{boolean cur=sp.getBoolean(doneKey(today,m),false);sp.edit().putBoolean(doneKey(today,m),!cur).apply();renderMeals();updateDashboard();});swapBtn.setOnClickListener(v->{int cur=sp.getInt("swap_"+today+"_"+m,-1);sp.edit().putInt("swap_"+today+"_"+m,cur+1).apply();renderMeals();});mealsBox.addView(box);}updateDashboard();}
 String doneKey(int d,int m){String date=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());return"done_"+date+"_"+d+"_"+m;}void updateDashboard(){int used=0,count=0;for(int m=0;m<4;m++)if(sp.getBoolean(doneKey(today,m),false)){used+=MealData.mealCalories(calories,m);count++;}caloriesLeft.setText(Math.max(0,calories-used)+" سعرة");completedCount.setText(count+" / 4");}
 void addWeight(float v){String date=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()),raw=sp.getString("weights","");LinkedHashMap<String,Float>map=new LinkedHashMap<>();if(!raw.isEmpty())for(String r:raw.split(";")){String[]p=r.split(",");if(p.length==2)try{map.put(p[0],Float.parseFloat(p[1]));}catch(Exception ignored){}}map.put(date,v);StringBuilder sb=new StringBuilder();for(Map.Entry<String,Float>e:map.entrySet()){if(sb.length()>0)sb.append(";");sb.append(e.getKey()).append(",").append(e.getValue());}sp.edit().putString("weights",sb.toString()).apply();}
 void renderWeight(){String raw=sp.getString("weights","");List<Float>vals=new ArrayList<>();String lastDate="",lastVal="";if(!raw.isEmpty())for(String r:raw.split(";")){String[]p=r.split(",");if(p.length==2)try{vals.add(Float.parseFloat(p[1]));lastDate=p[0];lastVal=p[1];}catch(Exception ignored){}}chart.setValues(vals);latestWeight.setText(lastVal.isEmpty()?"آخر وزن: —":"آخر وزن: "+lastVal+" كغ   ("+lastDate+")");}
 void saveProfile(){sp.edit().putString("name",name.getText().toString()).putString("age",age.getText().toString()).putInt("sex",sex.getSelectedItemPosition()).putString("height",height.getText().toString()).putString("weight",weight.getText().toString()).putString("target",target.getText().toString()).putInt("activity",activity.getSelectedItemPosition()).putInt("goal",goal.getSelectedItemPosition()).putInt("calories",calories).apply();}
 void saveTimes(){sp.edit().putString("time_breakfast",tBreakfast.getText().toString().trim()).putString("time_snack",tSnack.getText().toString().trim()).putString("time_lunch",tLunch.getText().toString().trim()).putString("time_dinner",tDinner.getText().toString().trim()).apply();}
 void load(){name.setText(sp.getString("name","محمد"));age.setText(sp.getString("age","47"));sex.setSelection(sp.getInt("sex",0));height.setText(sp.getString("height","180"));weight.setText(sp.getString("weight","105"));target.setText(sp.getString("target","90"));activity.setSelection(sp.getInt("activity",0));goal.setSelection(sp.getInt("goal",0));tBreakfast.setText(sp.getString("time_breakfast","08:00"));tSnack.setText(sp.getString("time_snack","13:00"));tLunch.setText(sp.getString("time_lunch","17:30"));tDinner.setText(sp.getString("time_dinner","20:30"));waterSwitch.setChecked(sp.getBoolean("water_enabled",false));calories=sp.getInt("calories",1850);}
 void requestNotif(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},99);}
}
